        $client = $this->createClientWithDiscovery();

        $authenticator = new OpenIdConnectAuthenticator(
            'https://api.example.com',
            'https://auth.example.com/.well-known/openid-configuration',
            'my-client-id',
            'my-client-secret',
            'https://app.example.com/callback',
            ['openid', 'profile']
